INSERT INTO source_grounded_claims_v21 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,dedupe_key,article_allowed) VALUES ('kg21_origin_narratives_two_sources','歷史敘事邊界','原民會英文頁以公開摘要列出卑南族起源敘事有「竹生」與「石生」兩種來源，但平台不得將其擴寫成未經授權的神話細節。',CAST('["cip_pinuyumayan_profile_en_2021_lines_113_216"]' AS JSON),'L119-L119','high','medium','public_summary_only','verified_source_public_summary','claim_e0d1986218a7d6fc','claim_e0d1986218a7d6fc',TRUE) ON DUPLICATE KEY UPDATE statement_zh=VALUES(statement_zh), review_status=VALUES(review_status);
